sys_script_include.script:
var PolicyLifecycleService = Class.create();

// Party roles are ONE vocabulary on submission_party.role and policy_party.party_role;
// roles that do not belong on an issued policy are not carried.
PolicyLifecycleService.SKIP_ROLES = ['third_party'];

PolicyLifecycleService.prototype = {

    initialize: function () {
        this.C = Constants.CHOICE;
        this.T = Constants.TABLE;
        this.policies = new LocalPolicyProvider();
    },

    // ------------------------------------------------------------- transactions
    // New business from an accepted quote option. opts: { submission, policyNumber, effectiveDate, expiryDate }
    issueNewBusiness: function (quoteOptionId, opts) {
        opts = opts || {};
        var qo = this._get(this.T.QUOTE_OPTION, quoteOptionId, 'quote_option');
        var quote = this._get(this.T.QUOTE, qo.getValue('quote'), 'quote');
        var submissionId = opts.submission || quote.getValue('submission') || '';
        var eff = opts.effectiveDate || quote.getValue('effective_date');
        var exp = opts.expiryDate || quote.getValue('expiration_date') || this._plusYears(eff, 1);
        var total = this._optionTotal(qo);

        var policy = new GlideRecord(this.T.POLICY);
        policy.initialize();
        policy.setValue('insured', quote.getValue('insured'));
        policy.setValue('insured_name', quote.insured.getDisplayValue());
        policy.setValue('product', qo.getValue('product') || quote.getValue('product'));
        policy.setValue('business_line', this._businessLine(qo));
        policy.setValue('quote_option', qo.getUniqueValue());
        policy.setValue('originating_submission', submissionId);
        policy.setValue('currency', quote.getValue('currency'));
        policy.setValue('system_of_record', this.C.SYSTEM_OF_RECORD.LOCAL);
        policy.setValue('inception_date', eff);
        policy.setValue('status', this.C.POLICY_STATUS.PENDING_ISSUE);
        policy.setValue('policy_number', opts.policyNumber || '');
        var policyId = policy.insert();
        if (!policy.getValue('policy_number')) {
            policy.setValue('policy_number', policy.getValue('number'));
            policy.update();
        }

        var term = this._newTerm(policyId, 1, eff, exp, submissionId, '', total, quote.getValue('currency'));
        var version = this._newVersion(policyId, term, 1, eff, this.C.TRANSACTION_TYPE.NEW_BUSINESS, total, total, submissionId, quoteOptionId, 'New business');
        this._snapshotFromQuoteOption(version, qo, submissionId);
        this._transaction(policyId, term, version, this.C.TRANSACTION_TYPE.NEW_BUSINESS, eff, total, submissionId, quoteOptionId, 'Policy issued');
        this._activate(policyId, term, version);
        return { policy: policyId, term: term, version: version };
    },

    // Mid-term adjustment. opts: { effectiveDate, quoteOption (re-priced terms) | null, submission, reason }
    endorse: function (policyId, opts) {
        opts = opts || {};
        var cur = this._current(policyId);
        var eff = opts.effectiveDate || this._today();
        var prevTotal = parseFloat(cur.version.getValue('total_premium')) || 0;
        var newTotal = opts.quoteOption ? this._optionTotal(this._get(this.T.QUOTE_OPTION, opts.quoteOption, 'quote_option')) : prevTotal;
        var delta = this._proRata(newTotal - prevTotal, cur.term, eff);
        var version = this._newVersion(policyId, cur.term.getUniqueValue(), this._nextVersionNo(cur.term.getUniqueValue()), eff,
            this.C.TRANSACTION_TYPE.ENDORSEMENT, newTotal, delta, opts.submission || '', opts.quoteOption || '', opts.reason || 'Mid-term adjustment');
        if (opts.quoteOption)
            this._snapshotFromQuoteOption(version, this._get(this.T.QUOTE_OPTION, opts.quoteOption, 'quote_option'), opts.submission || '');
        else
            this._cloneSnapshot(cur.version.getUniqueValue(), version);
        this._transaction(policyId, cur.term.getUniqueValue(), version, this.C.TRANSACTION_TYPE.ENDORSEMENT, eff, delta, opts.submission || '', opts.quoteOption || '', opts.reason || 'Endorsement');
        this._supersede(cur.version);
        this._addToTermPremium(cur.term, delta);
        this._activate(policyId, cur.term.getUniqueValue(), version);
        return { policy: policyId, term: cur.term.getUniqueValue(), version: version, premium_delta: delta };
    },

    // Renewal = a new term. opts: { quoteOption, submission }
    renew: function (policyId, opts) {
        opts = opts || {};
        var cur = this._current(policyId);
        var eff = cur.term.getValue('expiry_date');
        var exp = this._plusYears(eff, 1);
        var qo = opts.quoteOption ? this._get(this.T.QUOTE_OPTION, opts.quoteOption, 'quote_option') : null;
        var total = qo ? this._optionTotal(qo) : (parseFloat(cur.version.getValue('total_premium')) || 0);
        var termNo = (parseInt(cur.term.getValue('term_number'), 10) || 1) + 1;
        var term = this._newTerm(policyId, termNo, eff, exp, opts.submission || '', cur.term.getUniqueValue(), total, cur.term.getValue('currency'));
        var version = this._newVersion(policyId, term, 1, eff, this.C.TRANSACTION_TYPE.RENEWAL, total, total, opts.submission || '', opts.quoteOption || '', 'Renewal term ' + termNo);
        if (qo)
            this._snapshotFromQuoteOption(version, qo, opts.submission || '');
        else
            this._cloneSnapshot(cur.version.getUniqueValue(), version);
        this._transaction(policyId, term, version, this.C.TRANSACTION_TYPE.RENEWAL, eff, total, opts.submission || '', opts.quoteOption || '', 'Renewed');
        cur.term.setValue('status', this.C.POLICY_TERM_STATUS.RENEWED);
        cur.term.update();
        this._supersede(cur.version);
        this._activate(policyId, term, version);
        return { policy: policyId, term: term, version: version };
    },

    // opts: { effectiveDate, reason }. Return premium is pro-rata unearned.
    cancel: function (policyId, opts) {
        opts = opts || {};
        var cur = this._current(policyId);
        var eff = opts.effectiveDate || this._today();
        var total = parseFloat(cur.version.getValue('total_premium')) || 0;
        var refund = -this._proRata(total, cur.term, eff);
        var version = this._newVersion(policyId, cur.term.getUniqueValue(), this._nextVersionNo(cur.term.getUniqueValue()), eff,
            this.C.TRANSACTION_TYPE.CANCELLATION, total + refund, refund, '', '', opts.reason || 'Cancellation');
        this._cloneSnapshot(cur.version.getUniqueValue(), version);
        this._transaction(policyId, cur.term.getUniqueValue(), version, this.C.TRANSACTION_TYPE.CANCELLATION, eff, refund, '', '', opts.reason || 'Cancelled');
        this._supersede(cur.version);
        cur.term.setValue('status', this.C.POLICY_TERM_STATUS.CANCELLED);
        cur.term.setValue('cancellation_date', eff);
        cur.term.setValue('cancellation_reason', opts.reason || '');
        cur.term.update();
        this._addToTermPremium(cur.term, refund);
        this._activate(policyId, cur.term.getUniqueValue(), version, this.C.POLICY_STATUS.CANCELLED);
        return { policy: policyId, version: version, premium_delta: refund };
    },

    reinstate: function (policyId, opts) {
        opts = opts || {};
        var cur = this._current(policyId);
        var eff = opts.effectiveDate || cur.term.getValue('cancellation_date') || this._today();
        var cancelledTotal = parseFloat(cur.version.getValue('total_premium')) || 0;
        var prior = this._previousVersion(cur.version);
        var restored = prior ? (parseFloat(prior.getValue('total_premium')) || 0) : cancelledTotal;
        var delta = restored - cancelledTotal;
        var version = this._newVersion(policyId, cur.term.getUniqueValue(), this._nextVersionNo(cur.term.getUniqueValue()), eff,
            this.C.TRANSACTION_TYPE.REINSTATEMENT, restored, delta, '', '', opts.reason || 'Reinstatement');
        this._cloneSnapshot(cur.version.getUniqueValue(), version);
        this._transaction(policyId, cur.term.getUniqueValue(), version, this.C.TRANSACTION_TYPE.REINSTATEMENT, eff, delta, '', '', opts.reason || 'Reinstated');
        this._supersede(cur.version);
        cur.term.setValue('status', this.C.POLICY_TERM_STATUS.IN_FORCE);
        cur.term.setValue('cancellation_date', '');
        cur.term.update();
        this._addToTermPremium(cur.term, delta);
        this._activate(policyId, cur.term.getUniqueValue(), version);
        return { policy: policyId, version: version, premium_delta: delta };
    },

    // ------------------------------------------------------------- building blocks
    _newTerm: function (policyId, termNo, eff, exp, submissionId, renewedFrom, premium, currency) {
        var t = new GlideRecord(this.T.POLICY_TERM);
        t.initialize();
        t.setValue('policy', policyId);
        t.setValue('term_number', termNo);
        t.setValue('effective_date', eff);
        t.setValue('expiry_date', exp);
        t.setValue('status', this.C.POLICY_TERM_STATUS.IN_FORCE);
        t.setValue('written_premium', premium);
        t.setValue('currency', currency || '');
        t.setValue('originating_submission', submissionId || '');
        t.setValue('renewed_from_term', renewedFrom || '');
        t.setValue('system_of_record', this.C.SYSTEM_OF_RECORD.LOCAL);
        return t.insert();
    },

    _newVersion: function (policyId, termId, versionNo, eff, txType, total, delta, submissionId, quoteOptionId, summary) {
        var p = this._get(this.T.POLICY, policyId, 'policy');
        var v = new GlideRecord(this.T.POLICY_VERSION);
        v.initialize();
        v.setValue('policy', policyId);
        v.setValue('policy_term', termId);
        v.setValue('version_number', versionNo);
        v.setValue('transaction_effective_date', eff);
        v.setValue('transaction_type', txType);
        v.setValue('status', this.C.POLICY_VERSION_STATUS.ISSUED);
        v.setValue('is_current', false);
        v.setValue('total_premium', this._round(total));
        v.setValue('premium_delta', this._round(delta));
        v.setValue('currency', p.getValue('currency'));
        v.setValue('business_line', p.getValue('business_line'));
        v.setValue('product', p.getValue('product'));
        v.setValue('source_submission', submissionId || '');
        v.setValue('source_quote_option', quoteOptionId || '');
        v.setValue('change_summary', summary || '');
        v.setValue('issued_on', new GlideDateTime());
        v.setValue('system_of_record', this.C.SYSTEM_OF_RECORD.LOCAL);
        return v.insert();
    },

    _transaction: function (policyId, termId, versionId, type, eff, delta, submissionId, quoteOptionId, description) {
        var tx = new GlideRecord(this.T.POLICY_TRANSACTION);
        tx.initialize();
        tx.setValue('policy', policyId);
        tx.setValue('policy_term', termId);
        tx.setValue('policy_version', versionId);
        tx.setValue('type', type);
        tx.setValue('status', this.C.TRANSACTION_STATUS.COMPLETED);
        tx.setValue('effective_date', eff);
        tx.setValue('premium_delta', this._round(delta));
        tx.setValue('submission', submissionId || '');
        tx.setValue('quote_option', quoteOptionId || '');
        tx.setValue('name', description);
        tx.setValue('description', description);
        tx.setValue('processed_on', new GlideDateTime());
        return tx.insert();
    },

    // Policy header = rollup of the current term/version (kept for existing UI).
    _activate: function (policyId, termId, versionId, policyStatus) {
        var v = this._get(this.T.POLICY_VERSION, versionId, 'policy_version');
        v.setValue('is_current', true);
        v.update();
        var t = this._get(this.T.POLICY_TERM, termId, 'policy_term');
        var p = this._get(this.T.POLICY, policyId, 'policy');
        p.setValue('current_term', termId);
        p.setValue('current_version', versionId);
        p.setValue('effective_date', t.getValue('effective_date'));
        p.setValue('expiry_date', t.getValue('expiry_date'));
        p.setValue('total_premium', v.getValue('total_premium'));
        p.setValue('status', policyStatus || this.C.POLICY_STATUS.IN_FORCE);
        p.update();
        new IntegrationEventPublisher().publish({
            eventType: 'policy.' + v.getValue('transaction_type'),
            aggregate: 'policy_version', table: this.T.POLICY_VERSION, sysId: versionId
        });
    },

    _supersede: function (versionGr) {
        versionGr.setValue('status', this.C.POLICY_VERSION_STATUS.SUPERSEDED);
        versionGr.setValue('is_current', false);
        versionGr.update();
    },

    // Quote option -> policy version snapshot: risks, coverages, terms, parties, forms, commissions.
    _snapshotFromQuoteOption: function (versionId, qo, submissionId) {
        var v = this._get(this.T.POLICY_VERSION, versionId, 'policy_version');
        var policyId = v.getValue('policy');
        var riskMap = {};
        var qr = new GlideRecord(this.T.QUOTE_RISK);
        qr.addQuery('quote', qo.getValue('quote'));
        qr.query();
        while (qr.next()) {
            var pr = new GlideRecord(this.T.POLICY_RISK);
            pr.initialize();
            pr.setValue('policy', policyId);
            pr.setValue('policy_version', versionId);
            var fields = ['name', 'risk_type', 'construction', 'occupancy', 'protection', 'exposure', 'location', 'insurable_object'];
            for (var i = 0; i < fields.length; i++)
                pr.setValue(fields[i], qr.getValue(fields[i]));
            pr.setValue('sum_insured', this._riskValue(qo.getUniqueValue(), qr.getUniqueValue()));
            riskMap[qr.getUniqueValue()] = pr.insert();
        }
        // coverages at policy / line / jurisdiction / object level, keeping parent-child nesting
        var covMap = {}, parentOf = {};
        var qc = new GlideRecord(this.T.QUOTE_OPTION_COVERAGE);
        qc.addQuery('quote_option', qo.getUniqueValue());
        qc.addQuery('selected', true);
        qc.query();
        while (qc.next()) {
            var pc = new GlideRecord(this.T.POLICY_COVERAGE);
            pc.initialize();
            pc.setValue('policy', policyId);
            pc.setValue('policy_version', versionId);
            pc.setValue('coverage', qc.getValue('coverage'));
            pc.setValue('name', qc.getValue('name'));
            pc.setValue('coverage_premium', qc.getValue('premium'));
            pc.setValue('policy_risk', riskMap[qc.getValue('quote_risk')] || '');
            pc.setValue('scope_level', qc.getValue('scope_level') || (qc.getValue('quote_risk') ? this.C.COVERAGE_SCOPE.INSURABLE_OBJECT : this.C.COVERAGE_SCOPE.LINE));
            pc.setValue('jurisdiction', qc.getValue('jurisdiction'));
            pc.setValue('insurable_object', qc.getValue('insurable_object') || qc.quote_risk.insurable_object.toString());
            pc.setValue('status', this.C.POLICY_COVERAGE_STATUS.ACTIVE);
            var pcId = pc.insert();
            covMap[qc.getUniqueValue()] = pcId;
            if (qc.getValue('parent_coverage'))
                parentOf[pcId] = qc.getValue('parent_coverage');
            this._termsFromQuote(versionId, pcId, qc);
        }
        for (var child in parentOf) {
            var fix = new GlideRecord(this.T.POLICY_COVERAGE);
            if (parentOf.hasOwnProperty(child) && fix.get(child)) {
                fix.setValue('parent_coverage', covMap[parentOf[child]] || '');
                fix.update();
            }
        }
        if (submissionId)
            this._partiesFromSubmission(policyId, versionId, submissionId);
        this._formsFromProduct(versionId, qo.getValue('product') || v.getValue('product'));
        var cm = new GlideRecord(this.T.COMMISSION);
        cm.addQuery('quote_option_line.quote_option', qo.getUniqueValue());
        cm.query();
        while (cm.next()) {
            var c2 = new GlideRecord(this.T.COMMISSION);
            c2.initialize();
            var cf = ['producer', 'commission_type', 'rate', 'amount', 'split_pct'];
            for (var j = 0; j < cf.length; j++)
                c2.setValue(cf[j], cm.getValue(cf[j]));
            c2.setValue('policy_version', versionId);
            c2.insert();
        }
    },

    // Terms: explicit quote terms win (any level, basis, peril, %, min/max, nesting);
    // the option-coverage limit / deductible columns are carried only when no explicit term of that type exists.
    _termsFromQuote: function (versionId, policyCoverageId, qc) {
        var termMap = {}, parentOf = {}, has = {};
        var qt = new GlideRecord(this.T.QUOTE_OPTION_COVERAGE_TERM);
        qt.addQuery('quote_option_coverage', qc.getUniqueValue());
        qt.orderBy('display_order');
        qt.query();
        while (qt.next()) {
            var type = String(qt.getValue('term_type') || qt.coverage_term.term_type || this.C.POLICY_TERM_TYPE.SUBLIMIT);
            if (type === 'percentage') type = this.C.POLICY_TERM_TYPE.COINSURANCE;
            if (type === 'duration') type = this.C.POLICY_TERM_TYPE.WAITING_PERIOD;
            has[type] = true;
            var t = new GlideRecord(this.T.POLICY_COVERAGE_TERM);
            t.initialize();
            t.setValue('policy_coverage', policyCoverageId);
            t.setValue('policy_version', versionId);
            t.setValue('coverage_term', qt.getValue('coverage_term'));
            t.setValue('term_name', qt.getValue('name') || String(qt.coverage_term.term_name));
            t.setValue('term_type', type);
            t.setValue('selected_value', qt.getValue('term_value'));
            t.setValue('selected_label', String(qt.coverage_term_option.option_label || qt.getValue('term_value') || ''));
            var f = ['limit_basis', 'scope_level', 'jurisdiction', 'insurable_object', 'cause_of_loss', 'percentage', 'minimum_amount', 'maximum_amount', 'currency'];
            for (var i = 0; i < f.length; i++)
                t.setValue(f[i], qt.getValue(f[i]));
            var tid = t.insert();
            termMap[qt.getUniqueValue()] = tid;
            if (qt.getValue('parent_term'))
                parentOf[tid] = qt.getValue('parent_term');
        }
        for (var child in parentOf) {
            var fix = new GlideRecord(this.T.POLICY_COVERAGE_TERM);
            if (parentOf.hasOwnProperty(child) && fix.get(child)) {
                fix.setValue('parent_term', termMap[parentOf[child]] || '');
                fix.update();
            }
        }
        var scope = qc.getValue('scope_level') || this.C.COVERAGE_SCOPE.LINE;
        if (!has[this.C.POLICY_TERM_TYPE.LIMIT])
            this._termRow(versionId, policyCoverageId, 'Limit', this.C.POLICY_TERM_TYPE.LIMIT, qc.getValue('limit'), scope, qc.getValue('insurable_object'));
        if (!has[this.C.POLICY_TERM_TYPE.DEDUCTIBLE])
            this._termRow(versionId, policyCoverageId, 'Deductible', this.C.POLICY_TERM_TYPE.DEDUCTIBLE, qc.getValue('deductible'), scope, qc.getValue('insurable_object'));
    },

    _termRow: function (versionId, policyCoverageId, name, type, value, scope, objectId) {
        if (value === null || value === undefined || value === '')
            return;
        var t = new GlideRecord(this.T.POLICY_COVERAGE_TERM);
        t.initialize();
        t.setValue('policy_coverage', policyCoverageId);
        t.setValue('policy_version', versionId);
        t.setValue('term_name', name);
        t.setValue('term_type', type);
        t.setValue('scope_level', scope || this.C.COVERAGE_SCOPE.LINE);
        t.setValue('insurable_object', objectId || '');
        t.setValue('selected_value', value);
        t.setValue('selected_label', String(value));
        t.insert();
    },

    _partiesFromSubmission: function (policyId, versionId, submissionId) {
        var sp = new GlideRecord(this.T.SUBMISSION_PARTY);
        sp.addQuery('submission', submissionId);
        sp.query();
        while (sp.next()) {
            var role = String(sp.getValue('role') || '');
            if (!role || PolicyLifecycleService.SKIP_ROLES.indexOf(role) > -1 || !sp.getValue('organization'))
                continue;
            var pp = new GlideRecord(this.T.POLICY_PARTY);
            pp.initialize();
            pp.setValue('policy', policyId);
            pp.setValue('policy_version', versionId);
            pp.setValue('account', sp.getValue('organization'));
            pp.setValue('name', sp.organization.getDisplayValue());
            pp.setValue('party_role', role);
            pp.setValue('interest_type', sp.getValue('interest_type'));
            pp.setValue('is_primary', String(sp.getValue('is_primary')) === '1' || String(sp.getValue('is_primary')) === 'true' ||
                role === this.C.SUBMISSION_PARTY_ROLE.PRIMARY_INSURED);
            pp.insert();
        }
    },

    _formsFromProduct: function (versionId, productId) {
        if (!productId)
            return;
        var pf = new GlideRecord(this.T.PRODUCT_FORM);
        pf.addQuery('product', productId);
        pf.addQuery('active', true);
        pf.addQuery('attachment_rule', this.C.FORM_ATTACHMENT_RULE.MANDATORY);
        pf.orderBy('display_order');
        pf.query();
        while (pf.next()) {
            var f = new GlideRecord(this.T.POLICY_FORM);
            f.initialize();
            f.setValue('policy_version', versionId);
            f.setValue('form', pf.getValue('form'));
            f.setValue('product_form', pf.getUniqueValue());
            f.setValue('edition_date', pf.form.edition_date.toString());
            f.setValue('sequence', pf.getValue('display_order'));
            f.insert();
        }
    },

    // Copies every snapshot row of one version onto another (unchanged MTA, cancel, reinstate).
    _cloneSnapshot: function (fromVersionId, toVersionId) {
        var riskMap = {}, covMap = {};
        var self = this;
        function copy(table, extra, onCopied) {
            var src = new GlideRecord(table);
            src.addQuery('policy_version', fromVersionId);
            src.query();
            while (src.next()) {
                var dst = new GlideRecord(table);
                dst.initialize();
                var els = src.getElements();
                for (var i = 0; i < els.length; i++) {
                    var n = els[i].getName();
                    if (n.indexOf('sys_') === 0 || n === 'number')
                        continue;
                    dst.setValue(n, src.getValue(n));
                }
                dst.setValue('policy_version', toVersionId);
                if (extra)
                    extra(src, dst);
                var newId = dst.insert();
                if (onCopied)
                    onCopied(src.getUniqueValue(), newId);
            }
        }
        copy(this.T.POLICY_RISK, null, function (o, n) { riskMap[o] = n; });
        var termMap = {};
        copy(this.T.POLICY_COVERAGE, function (s, d) { d.setValue('policy_risk', riskMap[s.getValue('policy_risk')] || ''); }, function (o, n) { covMap[o] = n; });
        copy(this.T.POLICY_COVERAGE_TERM, function (s, d) { d.setValue('policy_coverage', covMap[s.getValue('policy_coverage')] || ''); }, function (o, n) { termMap[o] = n; });
        this._repoint(this.T.POLICY_COVERAGE, toVersionId, 'parent_coverage', covMap);
        this._repoint(this.T.POLICY_COVERAGE_TERM, toVersionId, 'parent_term', termMap);
        copy(this.T.POLICY_PARTY);
        copy(this.T.POLICY_FORM);
        copy(this.T.COMMISSION);
        return self;
    },

    // ------------------------------------------------------------- helpers
    // after a clone, self-references still point at the source version's rows
    _repoint: function (table, versionId, field, idMap) {
        var gr = new GlideRecord(table);
        gr.addQuery('policy_version', versionId);
        gr.addNotNullQuery(field);
        gr.query();
        while (gr.next()) {
            if (idMap[gr.getValue(field)]) {
                gr.setValue(field, idMap[gr.getValue(field)]);
                gr.update();
            }
        }
    },

    _current: function (policyId) {
        var term = this.policies.getCurrentTerm(policyId);
        var version = this.policies.getCurrentVersion(policyId);
        if (!term || !version)
            throw new Error('[PolicyLifecycleService] policy has no current term/version: ' + policyId);
        return { term: term, version: version };
    },

    _previousVersion: function (versionGr) {
        var v = new GlideRecord(this.T.POLICY_VERSION);
        v.addQuery('policy_term', versionGr.getValue('policy_term'));
        v.addQuery('version_number', '<', versionGr.getValue('version_number'));
        v.addQuery('transaction_type', '!=', this.C.TRANSACTION_TYPE.CANCELLATION);
        v.orderByDesc('version_number');
        v.setLimit(1);
        v.query();
        return v.next() ? v : null;
    },

    _nextVersionNo: function (termId) {
        var ga = new GlideAggregate(this.T.POLICY_VERSION);
        ga.addQuery('policy_term', termId);
        ga.addAggregate('MAX', 'version_number');
        ga.query();
        return ga.next() ? (parseInt(ga.getAggregate('MAX', 'version_number'), 10) || 0) + 1 : 1;
    },

    _optionTotal: function (qo) {
        var ga = new GlideAggregate(this.T.QUOTE_OPTION_LINE);
        ga.addQuery('quote_option', qo.getUniqueValue());
        ga.addAggregate('SUM', 'commercial_premium');
        ga.query();
        var lines = ga.next() ? parseFloat(ga.getAggregate('SUM', 'commercial_premium')) || 0 : 0;
        return lines || parseFloat(qo.getValue('written_premium')) || parseFloat(qo.getValue('total_premium')) || 0;
    },

    _riskValue: function (quoteOptionId, quoteRiskId) {
        var ga = new GlideAggregate(this.T.QUOTE_OPTION_COVERAGE);
        ga.addQuery('quote_option', quoteOptionId);
        ga.addQuery('quote_risk', quoteRiskId);
        ga.addQuery('selected', true);
        ga.addAggregate('SUM', 'limit');
        ga.query();
        return ga.next() ? parseFloat(ga.getAggregate('SUM', 'limit')) || 0 : 0;
    },

    _businessLine: function (qo) {
        var line = new GlideRecord(this.T.QUOTE_OPTION_LINE);
        line.addQuery('quote_option', qo.getUniqueValue());
        line.addNotNullQuery('business_line');
        line.setLimit(1);
        line.query();
        if (line.next())
            return line.getValue('business_line');
        var p = new GlideRecord(this.T.PRODUCT);
        return p.get(qo.getValue('product')) ? p.getValue('business_line') : '';
    },

    _addToTermPremium: function (termGr, delta) {
        termGr.setValue('written_premium', this._round((parseFloat(termGr.getValue('written_premium')) || 0) + delta));
        termGr.update();
    },

    // Share of an annual amount for the days from eff to term expiry.
    _proRata: function (amount, termGr, eff) {
        var start = new GlideDateTime(termGr.getValue('effective_date') + ' 12:00:00').getNumericValue();
        var end = new GlideDateTime(termGr.getValue('expiry_date') + ' 12:00:00').getNumericValue();
        var from = new GlideDateTime(eff + ' 12:00:00').getNumericValue();
        if (end <= start)
            return this._round(amount);
        var share = Math.max(0, Math.min(1, (end - from) / (end - start)));
        return this._round(amount * share);
    },

    _plusYears: function (dateStr, n) {
        var g = new GlideDateTime(dateStr + ' 12:00:00');
        g.addYearsUTC(n);
        return g.getDate().getValue();
    },

    _today: function () {
        return new GlideDateTime().getLocalDate().getValue();
    },

    _round: function (n) {
        return Math.round((parseFloat(n) || 0) * 100) / 100;
    },

    _get: function (table, id, label) {
        var gr = new GlideRecord(table);
        if (!id || !gr.get(id))
            throw new Error('[PolicyLifecycleService] ' + label + ' not found: ' + id);
        return gr;
    },

    type: 'PolicyLifecycleService'
};
